<?php
function opsCatalog($pdo,$uid){$rows=opsAll($pdo,'SELECT c.* FROM business_catalog c LEFT JOIN aulieata_catalog_status a ON a.user_id=c.user_id AND a.item_id=c.id WHERE c.user_id=? AND COALESCE(a.archived,0)=0 ORDER BY c.id',[$uid]);return attachCatalogDetails($pdo,$uid,$rows);}
function opsItem($pdo,$uid,$id){$r=opsOne($pdo,'SELECT c.* FROM business_catalog c LEFT JOIN aulieata_catalog_status a ON a.user_id=c.user_id AND a.item_id=c.id WHERE c.user_id=? AND c.id=? AND COALESCE(a.archived,0)=0',[$uid,$id]);if(!$r)throw new RuntimeException('Позиция не найдена в вашем каталоге');return attachCatalogDetails($pdo,$uid,[$r])[0];}
function opsBatchRows($pdo,$uid){
    $reserved=[];foreach(opsAll($pdo,'SELECT batch_id,SUM(quantity) AS qty FROM ops_reservations WHERE user_id=? AND active=1 GROUP BY batch_id',[$uid]) as $r)$reserved[(int)$r['batch_id']]=(float)$r['qty'];
    $rows=opsRecords($pdo,$uid,'stock_batches');$today=localBusinessDay();foreach($rows as &$r){$d=$r['data'];$r['reserved']=$reserved[(int)$r['id']]??0;$r['free']=max(0,round((float)$d['quantity']-$r['reserved'],3));$r['eligible']=($d['condition']??'blocked')==='safe'&&(!($d['expires_on']??'')||($d['expires_on']??'')>=$today);}
    usort($rows,fn($a,$b)=>strcmp(($a['data']['expires_on']??'')?:'9999-12-31',($b['data']['expires_on']??'')?:'9999-12-31')?:($a['id']<=>$b['id']));return $rows;
}
function opsComponents($item){$d=$item['details'];$mode=$d['inventory_mode']??'untracked';if($mode==='stock')return [['item_id'=>(int)$item['id'],'quantity'=>1.0]];if($mode==='recipe'){$merged=[];foreach($d['recipe']??[] as $part){$id=(int)$part['item_id'];$merged[$id]=($merged[$id]??0)+(float)$part['quantity'];}$out=[];foreach($merged as $id=>$quantity)$out[]=['item_id'=>$id,'quantity'=>$quantity];return $out;}return [];}
function opsAvailable($item,$batches){$parts=opsComponents($item);if(!$parts)return null;$limit=INF;foreach($parts as $p){$total=0;foreach($batches as $b)if($b['eligible']&&(int)($b['data']['item_id']??0)===(int)$p['item_id'])$total+=$b['free'];$limit=min($limit,$total/max(0.001,(float)$p['quantity']));}return is_finite($limit)?floor($limit*1000)/1000:0;}
function opsPublicAvailability($pdo,$uid,$rows){$batches=opsBatchRows($pdo,$uid);foreach($rows as &$r){$i=opsItem($pdo,$uid,(int)$r['id']);$available=opsAvailable($i,$batches);$r['available_quantity']=$available;$r['service_minutes']=$i['details']['duration_minutes']??30;$r['kind']=$i['details']['kind']??'product';if($available!==null&&$available<0.001)$r['availability']='out_of_stock';}return $rows;}
function opsAllocate($needs,$batches){$allocations=[];$cost=0;$known=true;foreach($needs as $item=>$qty){$left=round($qty,3);foreach($batches as $b){if(!$b['eligible']||(int)($b['data']['item_id']??0)!==(int)$item||$b['free']<=0)continue;$take=min($left,$b['free']);if($take<=0)continue;$allocations[]=['batch_id'=>(int)$b['id'],'item_id'=>(int)$item,'quantity'=>round($take,3),'cost'=>(float)$b['data']['cost'],'expires_on'=>$b['data']['expires_on']??''];if((float)$b['data']['cost']<=0)$known=false;else $cost+=$take*(float)$b['data']['cost'];$left=round($left-$take,3);if($left<0.001)break;}if($left>=0.001)throw new RuntimeException('Недостаточно пригодного свободного остатка для одной из позиций. Обновите заказ.');}return ['allocations'=>$allocations,'cost'=>$known?round($cost,2):null];}
function opsCampaign($pdo,$uid,$code){
    if(!$code)return null;$code=mb_strtoupper(opsText($code,40));foreach(opsRecords($pdo,$uid,'ops_campaign') as $r){$d=$r['data'];if(($d['code']??'')!==$code)continue;if(empty($d['active'])||($d['valid_until']??'')<localBusinessDay())throw new RuntimeException('Акция закончилась');$p=opsGetRecord($pdo,$uid,(int)$d['promotion_id'],'promotion_drafts')['data'];$valid=false;foreach(publicBusinessPromotions($pdo,$uid) as $published)if((int)$published['id']===(int)$d['promotion_id'])$valid=true;if(!$valid)throw new RuntimeException('Акция временно недоступна: проверьте ресурс и срок');$used=0;foreach(opsAll($pdo,"SELECT payload FROM ops_orders WHERE user_id=? AND status NOT IN ('cancelled','refunded')",[$uid]) as $o){$body=json_decode($o['payload'],true);if((int)($body['campaign_id']??0)===(int)$r['id'])foreach($body['items'] as $line)if((int)$line['item_id']===(int)$d['item_id'])$used+=$line['quantity'];}$d['remaining']=max(0,(float)$d['quantity_limit']-$used);$d['id']=(int)$r['id'];$d['price']=(float)$p['offer_price'];$d['min_margin']=(float)$p['min_margin'];return $d;}throw new RuntimeException('Промокод не найден');
}
function opsQuote($pdo,$uid,$input,$campaignCode=''){
    if(!is_array($input)||!count($input)||count($input)>30)throw new RuntimeException('Добавьте от 1 до 30 позиций');
    $merged=[];foreach($input as $line){$id=(int)($line['item_id']??0);$qty=round(opsNumber($line['quantity']??0,0.001,10000),3);$merged[$id]=($merged[$id]??0)+$qty;}
    $type=businessProfile($pdo,$uid)['type'];$batches=opsBatchRows($pdo,$uid);$campaign=opsCampaign($pdo,$uid,$campaignCode);
    if($campaign&&!isset($merged[(int)$campaign['item_id']]))throw new RuntimeException('Промокод действует на другую позицию');
    // Reserve the promotion's exact batch before allocating other items by expiry.
    if($campaign){$target=(int)$campaign['item_id'];$merged=[$target=>$merged[$target]]+$merged;}
    $items=[];$totalCents=0;$cost=0;$costKnown=true;$demo=null;$warnings=[];$allocations=[];
    foreach($merged as $id=>$qty){
        $item=opsItem($pdo,$uid,$id);$d=$item['details'];
        if(!empty($d['business_type'])&&$d['business_type']!==$type)throw new RuntimeException('Позиция относится к другой сфере бизнеса');
        $itemDemo=($d['data_mode']??'live')==='demo';if($demo!==null&&$demo!==$itemDemo)throw new RuntimeException('Оформляйте демонстрационные и реальные позиции отдельными заказами');$demo=$itemDemo;
        if(($d['availability']??'unknown')!=='available')throw new RuntimeException($item['item_name'].': наличие требует уточнения у сотрудника');
        $price=(float)$item['item_price'];$parts=opsComponents($item);$itemCost=(float)$item['item_cost'];$promotion=$campaign&&(int)$campaign['item_id']===$id;$lineBatches=$batches;
        if(($d['inventory_mode']??'untracked')==='recipe'&&!$parts)throw new RuntimeException('Для блюда не заполнен состав');
        if($promotion){
            if($qty>$campaign['remaining'])throw new RuntimeException('Лимит акции исчерпан');
            $source=opsGetRecord($pdo,$uid,(int)$campaign['source_id'],$campaign['source_kind'])['data'];
            if((int)($source['item_id']??0)!==$id)throw new RuntimeException('Ресурс акции изменён. Проверьте предложение.');
            $price=$campaign['price'];
            if($campaign['source_kind']==='stock_batches'){
                if(($d['inventory_mode']??'')!=='stock')throw new RuntimeException('Акция требует учёта по партиям');
                $lineBatches=array_values(array_filter($batches,fn($b)=>(int)$b['id']===(int)$campaign['source_id']));
            }else{$itemCost=max($itemCost,(float)($source['cost']??0));}
        }
        $lineCost=null;
        if($parts){
            $needs=[];foreach($parts as $p){$component=opsItem($pdo,$uid,(int)$p['item_id']);if(($d['inventory_mode']??'')==='recipe'&&($component['details']['inventory_mode']??'untracked')!=='stock')throw new RuntimeException('Ингредиенты должны учитывать партии напрямую');if(($component['details']['data_mode']??'live')!==($d['data_mode']??'live'))throw new RuntimeException('Реальные и демонстрационные остатки нельзя смешивать');$needs[(int)$p['item_id']]=$qty*(float)$p['quantity'];}
            $allocation=opsAllocate($needs,$lineBatches);$lineCost=$allocation['cost'];
            foreach($allocation['allocations'] as $a){$allocations[]=$a;foreach($batches as &$b)if((int)$b['id']===$a['batch_id'])$b['free']=round($b['free']-$a['quantity'],3);unset($b);}
        }else{if($itemCost>0)$lineCost=round($qty*$itemCost,2);if(($d['kind']??'product')!=='service')$warnings[]=$item['item_name'].': физический остаток не подключён';}
        $lineCents=(int)round($price*$qty*100);
        if($promotion&&($lineCost===null||$lineCents<ceil($lineCost/(1-$campaign['min_margin']/100)*100-0.00001)))throw new RuntimeException('Цена акции требует пересчёта');
        if($lineCost===null)$costKnown=false;else $cost+=$lineCost;
        $totalCents+=$lineCents;$items[]=['item_id'=>$id,'name'=>$item['item_name'],'quantity'=>$qty,'unit'=>$d['unit']??'шт.','price'=>$price,'total'=>$lineCents/100,'kind'=>$d['kind']??'product'];
    }
    if($totalCents>100000000000)throw new RuntimeException('Слишком большая сумма');
    $out=['items'=>$items,'total'=>$totalCents/100,'cost'=>$costKnown?round($cost,2):null,'is_demo'=>(bool)$demo,'allocations'=>$allocations,'warnings'=>array_values(array_unique($warnings)),'campaign_id'=>$campaign['id']??null,'campaign_code'=>$campaign['code']??''];$out['hash']=hash('sha256',opsJson([$items,$out['total'],$out['is_demo'],$out['campaign_id']]));return $out;
}
function opsCampaignSlot($pdo,$uid,$quote,$at){
    if(empty($quote['campaign_id']))return;
    $campaign=opsGetRecord($pdo,$uid,(int)$quote['campaign_id'],'ops_campaign')['data'];if($campaign['source_kind']!=='business_capacity')return;
    $source=opsGetRecord($pdo,$uid,(int)$campaign['source_id'],'business_capacity')['data'];
    if(!$at||substr($at,0,10)!==($source['date']??''))throw new RuntimeException('Акция действует только при записи на дату указанного свободного окна');
}
function opsCreateOrder($pdo,$uid,$d,$source='web',$chat=null,$actor=null){
    $key=opsText($d['request_key']??'',80);if(!preg_match('/^[a-zA-Z0-9_-]{12,80}$/D',$key))throw new RuntimeException('Обновите форму заказа');
    return opsTx($pdo,$uid,function()use($pdo,$uid,$d,$source,$chat,$key,$actor){$old=opsOne($pdo,'SELECT id,status,is_demo FROM ops_orders WHERE user_id=? AND request_key=?',[$uid,$key]);if($old)return $old+['duplicate'=>true];$quote=opsQuote($pdo,$uid,$d['items']??[],$d['campaign_code']??'');if(empty($d['quote_hash'])||!hash_equals($quote['hash'],(string)$d['quote_hash']))throw new RuntimeException('Цена или состав изменились. Проверьте обновлённый расчёт.');opsCampaignSlot($pdo,$uid,$quote,$d['booking_at']??'');$quote['client']=opsText($d['client']??'Гость');$quote['phone']=opsText($d['phone']??'',50);$quote['note']=opsText($d['note']??'',1000);$quote['pickup_at']=opsText($d['pickup_at']??'',100);$quote['payment_status']='not_recorded';
        opsExec($pdo,"INSERT INTO ops_orders(user_id,request_key,status,source,chat_id,total,is_demo,payload,created_at) VALUES(?,?,'new',?,?,?,?,?,?)",[$uid,$key,$source,$chat,$quote['total'],$quote['is_demo']?1:0,opsJson($quote),opsNow()]);$id=(int)$pdo->lastInsertId();foreach($quote['allocations'] as $a)opsExec($pdo,'INSERT INTO ops_reservations(user_id,order_id,batch_id,quantity) VALUES(?,?,?,?) ON DUPLICATE KEY UPDATE quantity=quantity+VALUES(quantity)',[$uid,$id,$a['batch_id'],$a['quantity']]);opsAudit($pdo,$uid,'order_create',$id,['source'=>$source,'total'=>$quote['total'],'is_demo'=>$quote['is_demo']],$actor);return ['id'=>$id,'status'=>'new','total'=>$quote['total'],'is_demo'=>$quote['is_demo']];});
}
function opsOrderStatus($pdo,$uid,$id,$next,$restock=false,$fromAppointment=false){
    return opsTx($pdo,$uid,function()use($pdo,$uid,$id,$next,$restock,$fromAppointment){
        if(!$fromAppointment){$appointment=opsOne($pdo,"SELECT id FROM ops_appointments WHERE user_id=? AND JSON_UNQUOTE(JSON_EXTRACT(payload,'$.order_id'))=? LIMIT 1",[$uid,(string)$id]);if($appointment){$mapped=['accepted'=>'confirmed','completed'=>'completed','cancelled'=>'cancelled'];if(isset($mapped[$next]))return opsAppointmentStatus($pdo,$uid,(int)$appointment['id'],$mapped[$next]);if(in_array($next,['preparing','ready'],true))throw new RuntimeException('Для услуги используйте статусы записи');}}
