        if($next==='completed')foreach($d['allocations'] as $a){$b=opsGetRecord($pdo,$uid,$a['batch_id'],'stock_batches',true);$v=$b['data'];if(($v['condition']??'blocked')!=='safe'||(!empty($v['expires_on'])&&$v['expires_on']<$today)||(float)$v['quantity']+0.00001<$a['quantity'])throw new RuntimeException('Партия недоступна или истёк срок. Не выдавайте заказ; отмените его и соберите заново.');$v['quantity']=round($v['quantity']-$a['quantity'],3);opsPutRecord($pdo,$uid,$b['id'],$v);opsAudit($pdo,$uid,'stock_sale',$b['id'],['order_id'=>$id,'quantity'=>-$a['quantity']]);}
        if(in_array($next,['completed','cancelled']))opsExec($pdo,'UPDATE ops_reservations SET active=0 WHERE user_id=? AND order_id=?',[$uid,$id]);
        if($next==='refunded'){$d['refunded_at']=opsNow();$d['restocked']=(bool)$restock;if($restock)foreach($d['allocations'] as $a){$b=opsGetRecord($pdo,$uid,$a['batch_id'],'stock_batches',true);$v=$b['data'];if(($v['condition']??'blocked')!=='safe'||(!empty($v['expires_on'])&&$v['expires_on']<$today))throw new RuntimeException('Вернуть в продажу эту партию нельзя. Оформите возврат без пополнения остатка.');$v['quantity']=round($v['quantity']+$a['quantity'],3);opsPutRecord($pdo,$uid,$b['id'],$v);opsAudit($pdo,$uid,'stock_return',$b['id'],['order_id'=>$id,'quantity'=>$a['quantity']]);}}
        opsExec($pdo,'UPDATE ops_orders SET status=?,payload=?,completed_at=IF(?=\'completed\',?,completed_at) WHERE user_id=? AND id=?',[$next,opsJson($d),$next,opsNow(),$uid,$id]);opsAudit($pdo,$uid,'order_status',$id,['before'=>$old,'after'=>$next]);
