}
function opsSaveBatch($pdo,$uid,$id,$d){return opsTx($pdo,$uid,function()use($pdo,$uid,$id,$d){$clean=cleanOpportunityResource('stock_batches',$d);$clean['item_id']=(int)($d['item_id']??0);if($clean['item_id']){$item=opsItem($pdo,$uid,$clean['item_id']);if(($item['details']['inventory_mode']??'untracked')!=='stock')throw new RuntimeException('Для связанной позиции включите учёт «По партиям»');}$old=null;if($id){$old=opsGetRecord($pdo,$uid,$id,'stock_batches',true)['data'];$r=opsOne($pdo,'SELECT COALESCE(SUM(quantity),0) AS n FROM ops_reservations WHERE user_id=? AND batch_id=? AND active=1',[$uid,$id]);if((float)$r['n']>0&&((float)$clean['quantity']+0.00001<(float)$r['n']||(int)($old['item_id']??0)!==$clean['item_id']))throw new RuntimeException('Есть резерв по заказам. Сначала измените или отмените эти заказы.');opsPutRecord($pdo,$uid,$id,$clean);}else $id=opsRecord($pdo,$uid,'stock_batches',$clean);opsAudit($pdo,$uid,'batch_edit',$id,['before'=>$old,'after'=>$clean]);return ['id'=>$id,'ok'=>true];});}
function opsSaveCampaign($pdo,$uid,$d){$p=opsGetRecord($pdo,$uid,(int)$d['promotion_id'],'promotion_drafts')['data'];if(($p['status']??'')!=='published')throw new RuntimeException('Сначала проверьте и опубликуйте предложение в разделе акций');$sourceId=(int)$p['source_id'];$kind=opsOne($pdo,'SELECT kind FROM aulieata_records WHERE id=? AND user_id=?',[$sourceId,$uid])['kind']??'';if(!in_array($kind,['stock_batches','business_capacity']))throw new RuntimeException('Ресурс акции не найден');$source=opsGetRecord($pdo,$uid,$sourceId,$kind)['data'];$itemId=(int)($source['item_id']??0);if(!$itemId||$itemId!==(int)($d['item_id']??0))throw new RuntimeException('Свяжите исходный ресурс акции с этой позицией каталога');$item=opsItem($pdo,$uid,$itemId);if(($item['details']['inventory_mode']??'')==='recipe')throw new RuntimeException('Для акции на блюдо создайте отдельную готовую партию; скидка ингредиента не равна скидке блюда');$code=mb_strtoupper(opsText($d['code']??'',40));if(!preg_match('/^[A-Z0-9_-]{3,30}$/D',$code))throw new RuntimeException('Промокод: 3–30 латинских букв, цифр или дефисов');foreach(opsRecords($pdo,$uid,'ops_campaign') as $r)if($r['data']['code']===$code)throw new RuntimeException('Такой промокод уже существует');$id=opsRecord($pdo,$uid,'ops_campaign',['name'=>$p['name'],'code'=>$code,'promotion_id'=>(int)$d['promotion_id'],'source_id'=>$sourceId,'source_kind'=>$kind,'item_id'=>$itemId,'valid_until'=>$p['valid_until'],'quantity_limit'=>min((float)$p['quantity_limit'],(float)$source['quantity']),'active'=>true]);return ['id'=>$id,'code'=>$code];}
function opsReport($pdo,$uid,$from,$to){if(!validBusinessDate($from)||!validBusinessDate($to)||$from>$to)throw new RuntimeException('Проверьте период');$orders=opsAll($pdo,"SELECT * FROM ops_orders WHERE user_id=? AND is_demo=0 AND ((completed_at>=? AND completed_at<?) OR (status='refunded'))",[$uid,$from.' 00:00:00',(new DateTimeImmutable($to))->modify('+1 day')->format('Y-m-d').' 00:00:00']);$sales=0;$refunds=0;$cost=0;$unknown=0;$count=0;$bot=0;$campaigns=[];
    foreach($orders as $o){$d=json_decode($o['payload'],true);$day=substr($o['completed_at']??'',0,10);$sale=$day>=$from&&$day<=$to&&in_array($o['status'],['completed','refunded']);if($sale){$sales+=(float)$o['total'];$count++;if($o['source']==='telegram')$bot++;if($d['cost']===null)$unknown++;else $cost+=(float)$d['cost'];if(!empty($d['campaign_code'])){$key=$d['campaign_code'];$campaigns[$key]??=['orders'=>0,'sales'=>0];$campaigns[$key]['orders']++;$campaigns[$key]['sales']+=(float)$o['total'];}}$refundDay=substr($d['refunded_at']??'',0,10);if($o['status']==='refunded'&&$refundDay>=$from&&$refundDay<=$to)$refunds+=(float)$o['total'];}
    $expenses=0;foreach(opsRecords($pdo,$uid,'expenses') as $e){$day=$e['data']['date']??'';if($day>=$from&&$day<=$to)$expenses+=(float)$e['data']['amount'];}
    $bookings=opsOne($pdo,"SELECT COUNT(*) AS n FROM ops_appointments WHERE user_id=? AND status='completed' AND COALESCE(JSON_UNQUOTE(JSON_EXTRACT(payload,'$.is_demo')),'false') NOT IN ('true','1') AND starts_at>=? AND starts_at<?",[$uid,$from.' 00:00:00',(new DateTimeImmutable($to))->modify('+1 day')->format('Y-m-d').' 00:00:00']);$tickets=array_filter(opsRecords($pdo,$uid,'ops_ticket'),fn($r)=>($r['data']['status']??'open')!=='resolved');return ['from'=>$from,'to'=>$to,'completed_orders'=>$count,'telegram_orders'=>$bot,'sales'=>round($sales,2),'refunds'=>round($refunds,2),'net_sales'=>round($sales-$refunds,2),'known_cost'=>round($cost,2),'unknown_cost_orders'=>$unknown,'expenses'=>round($expenses,2),'gross_profit'=>$unknown||$refunds?null:round($sales-$cost,2),'after_expenses'=>$unknown||$refunds?null:round($sales-$cost-$expenses,2),'completed_visits'=>(int)$bookings['n'],'open_tickets'=>count($tickets),'campaigns'=>$campaigns,'note'=>'Управленческий отчёт по завершённым реальным заказам. Возвраты учитываются по дате отметки; денежный перевод система не выполняет. Себестоимость возвратов требует сверки. Демонстрационные заказы и старые агрегаты продаж исключены.'];}

function opsValidateCatalog($pdo,$uid,$id,$d){$sku=mb_strtolower($d['sku']??'');foreach(opsCatalog($pdo,$uid) as $item){if((int)$item['id']!==$id&&$sku&&mb_strtolower($item['details']['sku']??'')===$sku)throw new RuntimeException('Этот артикул уже используется');if((int)$item['id']!==$id&&($d['inventory_mode']??'')!=='stock')foreach($item['details']['recipe']??[] as $p)if((int)$p['item_id']===$id)throw new RuntimeException('Позиция используется в составе. Сначала измените состав связанных блюд.');}foreach($d['recipe']??[] as $p){if((int)$p['item_id']===$id)throw new RuntimeException('Позиция не может входить в собственный состав');$component=opsItem($pdo,$uid,(int)$p['item_id']);if(($component['details']['inventory_mode']??'')!=='stock')throw new RuntimeException('Ингредиент должен учитываться по партиям');if(($component['details']['data_mode']??'live')!==$d['data_mode'])throw new RuntimeException('Реальные и демонстрационные данные нельзя смешивать в составе');}if($id){try{$old=opsItem($pdo,$uid,$id)['details'];}catch(RuntimeException $ex){$old=[];}if(($old['unit']??'')!==($d['unit']??'')||($old['data_mode']??'live')!==$d['data_mode'])foreach(opsBatchRows($pdo,$uid) as $b)if((int)($b['data']['item_id']??0)===$id&&((float)$b['data']['quantity']>0||$b['reserved']>0))throw new RuntimeException('Есть остатки по партиям. Единицу и достоверность данных менять нельзя.');}}
